sys_script.script:
// BR7: Case Type Mandatory Enforcement
(function () {
    // Mandatory for users with analyst role (covers ir_team/manager via inheritance)
    if (gs.hasRole('x_2241073_securi_0.analyst')) {
        if (!current.getValue('case_type')) {
            gs.addErrorMessage('Case Type is required.');
            current.setAbortAction(true);
        }
    } else {
        // For non-analyst users, default case_type to Employee Report if empty
        if (!current.getValue('case_type')) {
            current.setValue('case_type', 'Employee Report');
        }
    }
})();
